CREATE TABLE IF NOT EXISTS p10_lucky_objects (guid VARCHAR(64) PRIMARY KEY, owner_id BIGINT NOT NULL, owner_name VARCHAR(128) NOT NULL, scene VARCHAR(64) NOT NULL, line INT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, frame LONGBLOB NOT NULL, reward VARCHAR(512) NOT NULL, reward_hash VARCHAR(64) NOT NULL, claimed_by BIGINT NOT NULL, claimed_at BIGINT NOT NULL, claim_response LONGBLOB NULL, KEY idx_p10_lucky_owner(owner_id), KEY idx_p10_lucky_scope(scene,line,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
